-- First express u in terms of u₀ = u 1
have h_u : ∀ n, u n = u 1 + (n - 1) := by
  intro n
  induction n with d hd
  · simp [hd]
  · simp [hd, Nat.succ_eq_add_one, hd]

-- Let S = sum_{k=1 to 98} u k = 137
