  rw [h_u, Finset.sum_congr (λ k, u k.succ), h₁]
  rw [Finset.sum_range, Finset.sum_range, Finset.sum_const, Nat.div_two_eq_of_even]
  simp [Nat.mul_comm, Nat.add_comm, Nat.add_assoc, Nat.add_sub_cancel]

-- Solve for u 1
have h_u1 : u 1 = 137 - 4851 := by
  rw [h_S]
  simp [Nat.mul_comm, Nat.add_comm, Nat.add_assoc]

